import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-03-06","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-03-06","date":"2024-03-06T00:00:00.000Z","updated":"2024-03-07T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","存储重构","会议纪要"],"categories":["会议总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-03-06.md"};function r(n,l,s,p,h,u){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>会议日期与时间</strong>: 2024年3月6日</li><li><strong>参会人员</strong>: [列出参会人员]</li><li><strong>会议主持</strong>: [主持人姓名]</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>TC 崩溃问题</strong></p><ul><li>讨论了TC（Transport Client）版本2.8.1的崩溃问题，该问题在三年前被记录，但最近重新出现。</li><li>讨论了在SEF spec文件中直接处理此问题，而不是依赖于外部repo。</li><li>决定在SEF spec文件中拒绝版本2.8及其所有次要版本，以避免潜在的崩溃问题。</li></ul></li><li><p><strong>Zipper 相关 GCK 想法</strong></p><ul><li>Ali提出了关于zipper相关的GCK（Google Summer of Code）项目想法。</li><li>讨论了可能的zipper相关项目，并鼓励社区成员如果有任何想法，可以与Ali联系。</li></ul></li><li><p><strong>Redis 作为消息队列</strong></p><ul><li>讨论了使用Redis作为消息队列来替换现有的持久化通知系统。</li><li>提出了一些技术挑战和可能的解决方案，包括使用Boost Redis客户端。</li></ul></li><li><p><strong>DDoP 问题</strong></p><ul><li>讨论了在S3对象级别的数据重复问题（DDoP），并介绍了Gabriel编写的一个工具来检测这种重复。</li><li>发现某些集群中存在高达25%的重复率，鼓励社区成员使用该工具来评估他们的数据。</li></ul></li><li><p><strong>通知事件的可见性</strong></p><ul><li>讨论了如何提高通知事件的可见性，特别是在事件成功交付时的日志记录。</li><li>提出了将日志记录分为子系统的建议，以便更好地管理和监控。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>在SEF spec文件中拒绝版本2.8及其所有次要版本，以避免TC崩溃问题。</li><li>鼓励社区成员使用Gabriel的工具来检测S3对象级别的重复数据。</li><li>将日志记录分为子系统，以提高通知事件的可见性和管理。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>由相关人员提交PR，拒绝SEF spec文件中的版本2.8及其所有次要版本。</li><li>社区成员测试Gabriel的工具，并提供反馈。</li><li>实施日志子系统分割，以改善通知事件的日志记录。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>提醒社区成员在即将到来的SEF用户和开发者会议上讨论DDoP工具。</li><li>鼓励社区成员思考GCK项目的想法，并与Ali联系。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，主持人感谢所有参与者的贡献，并期待下次会议。</li></ul><p>在原始字幕中，以下信息可能存在误解或遗漏：</p><ul><li>关于TC崩溃问题的讨论可能存在一些细节上的不一致，需要进一步澄清。</li><li>关于Redis作为消息队列的讨论可能需要进一步的技术细节。</li><li>关于DDoP问题的讨论可能需要更详细的工具使用说明。</li></ul><p>改进后的总结更准确地反映了会议的关键细节，讨论的主要议题，决定的事项以及后续的行动计划，并保留了相关的Ceph相关领域的英文原文关键词。</p>',16)])])}const _=i(o,[["render",r]]);export{c as __pageData,_ as default};
